(1506693, 199417, 39850, '<td valign="top">9 - Ahh, very good.</td>', '9 - Ahh, very good.', '2005-07-05 00:21:11.000000', NULL, 1),
(1506697, 196888, 30822, '<td valign="top">Gave it an 8. The drops on this are amazing. Light is just a bit flat to me. Bump the contrast and it would have been a 10. Good work!</td>', 'Gave it an 8. The drops on this are amazing. Light is just a bit flat to me. Bump the contrast and it would have been a 10. Good work!', '2005-07-05 00:23:06.000000', NULL, 1),
(1506702, 197894, 39850, '<td valign="top">8 - Yeah, great.  A tad more focus/detail would be better.  I get the concept, but I think ''he'' would be better ''used'' with a different background/foreground.  Great ''grasping'' of the red/orange though.</td>', '8 - Yeah, great.  A tad more focus/detail would be better.  I get the concept, but I think ''he'' would be better ''used'' with a different background/foreground.  Great ''grasping'' of the red/orange though.', '2005-07-05 00:23:45.000000', NULL, 1),
(1506703, 196891, 30822, '<td valign="top">Very cool and DOF. Might have POPed more for me in color though. 7.</td>', 'Very cool and DOF. Might have POPed more for me in color though. 7.', '2005-07-05 00:24:02.000000', NULL, 1),
(1506705, 196987, 30822, '<td valign="top">Very interesting and great composition. 8.</td>', 'Very interesting and great composition. 8.', '2005-07-05 00:24:34.000000', NULL, 1),
(1506707, 199471, 39850, '<td valign="top">7 - This is nice, but I would like to have seen either the stem in focus or no stem at all.</td>', '7 - This is nice, but I would like to have seen either the stem in focus or no stem at all.', '2005-07-05 00:25:05.000000', NULL, 1),
