INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1507364, 198022, 39347, '<td valign="top">Maybe alittle more focus on the backround and not so much on the chain.</td>', 'Maybe alittle more focus on the backround and not so much on the chain.', '2005-07-05 07:58:12.000000', NULL, 1),
(1507372, 197960, 39850, '<td valign="top">8 - Very nice.</td>', '8 - Very nice.', '2005-07-05 08:11:42.000000', NULL, 1),
(1507375, 199649, 39850, '<td valign="top">7 - Nice colors.  For me, sharper marble focus if possible would have been better, possibly lighter too, not sure.</td>', '7 - Nice colors.  For me, sharper marble focus if possible would have been better, possibly lighter too, not sure.', '2005-07-05 08:18:41.000000', NULL, 1),
(1507377, 199344, 39850, '<td valign="top">7 - Good.  For me, a close up of the head, especially the eye(s) would have made this a better shot.  Nice big eyes.</td>', '7 - Good.  For me, a close up of the head, especially the eye(s) would have made this a better shot.  Nice big eyes.', '2005-07-05 08:20:19.000000', NULL, 1),
(1507379, 199048, 39850, '<td valign="top">7 - Good concept.  Nice swirls.  For me, would like it much closer and more detail.  I like the red ''frame''/background, but a different texture (perhaps not fabric, though I think you were going for a ''swirl'' with that too) for me, would have made this a more interesting and unique picture.</td>', '7 - Good concept.  Nice swirls.  For me, would like it much closer and more detail.  I like the red ''frame''/background, but a different texture (perhaps not fabric, though I think you were going for a ''swirl'' with that too) for me, would have made this a more interesting and unique picture.', '2005-07-05 08:23:40.000000', NULL, 1),
(1507380, 199101, 39850, '<td valign="top">7 - Very nice.  For me, the stigma in focus would have made this a better photograph.  Nice simple beauty though.  Good colors.</td>', '7 - Very nice.  For me, the stigma in focus would have made this a better photograph.  Nice simple beauty though.  Good colors.', '2005-07-05 08:25:04.000000', NULL, 1),
(1507381, 198288, 23614, '<td valign="top">Are you one who didn''t want bugs in this challenge? ;-) Picture seems ok to me except for that reflexion at the top.</td>', 'Are you one who didn''t want bugs in this challenge? ;-) Picture seems ok to me except for that reflexion at the top.', '2005-07-05 08:25:20.000000', NULL, 1),
