(1508481, 199536, 19311, '<td valign="top">A little to much going on in this picture.</td>', 'A little to much going on in this picture.', '2005-07-05 17:34:57.000000', NULL, 1),
(1508482, 199170, 22537, '<td valign="top">This shot is one of the coolest of the challenge. Excellent image and should be in the top 10.  Good luck!</td>', 'This shot is one of the coolest of the challenge. Excellent image and should be in the top 10.  Good luck!', '2005-07-05 17:34:59.000000', NULL, 1),
