(1519988, 199399, 3306, '<td valign="top">Good idea for the challenge. I like the colors. Softer lighting would have been more appealing.</td>', 'Good idea for the challenge. I like the colors. Softer lighting would have been more appealing.', '2005-07-08 22:07:03.000000', NULL, 1),
(1519990, 199500, 3306, '<td valign="top">Now that''s a picture I can sink my teeth into! Good job.</td>', 'Now that''s a picture I can sink my teeth into! Good job.', '2005-07-08 22:07:55.000000', NULL, 1),
(1519994, 199279, 3306, '<td valign="top">Interesting pattern. I like the color.</td>', 'Interesting pattern. I like the color.', '2005-07-08 22:08:47.000000', NULL, 1),
